      ["Hop on top of the next flower and advance to the left coast."] = "Запрыгни на следующий цветок и двигайся к левому берегу.", -- A_Classic_Fairytale:journey
      ["Horns"] = "Рога", -- 
      ["Hostage Situation"] = "Заложники", -- A_Classic_Fairytale:family
      ["How can I ever repay you for saving my life?"] = "Как я смогу отблагодарить тебя за спасение жизни?", -- A_Classic_Fairytale:journey
      ["How come in a village full of warriors, it's up to me to save it?"] = "Как же так: полная деревня воинов, а спасать её должен я?", -- A_Classic_Fairytale:dragon
      ["How could you betray us?"] = "Как ты мог предать нас?", -- A_Classic_Fairytale:queen
      ["How difficult would you like it to be?"] = "Какую сложность вы хотите выбрать?", -- A_Classic_Fairytale:first_blood
      ["HOW DO THEY KNOW WHERE WE ARE?"] = "ОТКУДА ОНИ ЗНАЮТ, ГДЕ МЫ?", -- A_Classic_Fairytale:united
      ["However, if you fail to do so, she dies a most violent death, just like your friend! Muahahaha!"] = "Но если не справишься, она умрёт самой страшной смертью, прямо как твой друг! Муа-ха-ха-ха!", -- A_Classic_Fairytale:journey
      ["However, if you fail to do so, she dies a most violent death! Muahahaha!"] = "Но если не справишься, она умрёт самой страшной смертью! Муа-ха-ха-ха!", -- A_Classic_Fairytale:journey
      ["However, my mates don't agree with me on letting you go..."] = "Однако мои приятели не согласны просто так тебя отпустить...", -- A_Classic_Fairytale:dragon
      ["However, the army of %s is about to attack any moment now."] = "Однако армия %s вот-вот нападёт с минуты на минуту.", -- A_Space_Adventure:fruit01
      ["How to Rope"] = "Как пользоваться верёвкой", -- Basic_Training_-_Rope
      ["How would you like being discriminated against?"] = "А вам бы понравилось, если бы вас притесняли?", -- A_Classic_Fairytale:queen
      ["Huh?"] = "А?", -- A_Classic_Fairytale:backstab, A_Classic_Fairytale:queen
      ["Hunter"] = "Охотник", --Bazooka, Shotgun, SniperRifle
      ["I ain't gonna sit around no more!"] = "Я больше не собираюсь сидеть сложа руки!", -- A_Classic_Fairytale:queen
      ["I already said I'm sorry!"] = "Я же уже извинился!", -- A_Classic_Fairytale:epil
      ["I always suspected him!"] = "Я всегда его подозревал!", -- A_Classic_Fairytale:epil
      ["I am going to leave the kids play by themselves."] = "Пойду оставлю детишек играть одних.", -- A_Classic_Fairytale:queen
      ["I am not ready for this planet yet. I should visit it when I have found all the other device parts."] = "Я ещё не готов к этой планете. Стоит наведаться сюда, когда найду все остальные детали устройства.", -- A_Space_Adventure:cosmos
      ["I am sorry but I was looking for a device that may be hidden somewhere around here."] = "Простите, но я искал устройство, которое может быть спрятано где-то здесь.", -- A_Space_Adventure:fruit02
      ["I believe there's more of them."] = "Полагаю, их там ещё больше.", -- A_Classic_Fairytale:backstab
      ["I cannot let you go any further! … burp …"] = "Я не могу пропустить вас дальше!… ик…", -- A_Classic_Fairytale:queen
      ["I can see you have been training diligently."] = "Вижу, ты усердно тренировался.", -- A_Classic_Fairytale:first_blood
      ["I can't believe how blind we were."] = "Не верится, какими слепыми мы были.", -- A_Classic_Fairytale:epil
      ["I can't believe it worked!"] = "Невероятно, это сработало!", -- A_Classic_Fairytale:shadow
      ["I can't believe this!"] = "Не могу в это поверить!", -- A_Classic_Fairytale:enemy
      ["I can't believe what I'm hearing!"] = "Не верю своим ушам!", -- A_Classic_Fairytale:backstab
      ["I can't let you go further because …"] = "Я не могу пустить вас дальше, потому что…", -- A_Classic_Fairytale:queen
      ["I can't wait any more, I have to save myself!"] = "Больше ждать нельзя, надо спасаться!", -- A_Classic_Fairytale:shadow
      ["Ice Jake"] = "Ледяной Джейк", -- A_Space_Adventure:ice01
      ["I could just teleport myself there..."] = "Я мог бы просто телепортироваться туда...", -- A_Classic_Fairytale:family
      ["Icy Girder: [3]"] = "Ледяная балка: [3]", -- HedgeEditor
      ["Icy Land: [3]"] = "Ледяная земля: [3]", -- HedgeEditor
      ["Icy Land"] = "Ледяная земля", -- HedgeEditor
      ["I'd better get going myself."] = "Пожалуй, мне лучше отправиться самому.", -- A_Classic_Fairytale:journey
      ["Identity Thief"] = "Похититель личности", -- Mutant
      ["I didn't until about a month ago."] = "До прошлого месяца не знал.", -- A_Classic_Fairytale:enemy
      ["I don't care. It's worth a fortune! Good bye, you idiot!"] = "Мне плевать. Она стоит целое состояние! Прощай, идиот!", -- A_Space_Adventure:fruit02
      ["I don't know how you did that. But good work!|The next one should be easy as cake for you!"] = "Не знаю, как вы это сделали, но отличная работа!|Следующая цель покажется вам пустяком!", -- Basic_Training_-_Rope
      ["I don't know if I can forget what you've done!"] = "Не знаю, смогу ли забыть то, что ты натворила!", -- A_Classic_Fairytale:epil
      ["I don't know who I can trust anymore."] = "Я больше не знаю, кому можно доверять.", -- A_Classic_Fairytale:epil
      ["I don't like your tone! You're hurting me!"] = "Мне не нравится твой тон! Ты делаешь мне больно!", -- A_Classic_Fairytale:queen
      ["I feel something...a place! They will arrive near the circles!"] = "Я что-то чувствую... место! Они появятся возле кругов!", -- A_Classic_Fairytale:backstab
      ["If only I had a way..."] = "Вот бы у меня был способ...", -- A_Classic_Fairytale:backstab
      ["If only I were given a chance to explain my being here..."] = "Вот бы мне дали шанс объяснить, зачем я здесь...", -- A_Classic_Fairytale:first_blood
      ["If only one enemy is left, you'll get bonus ammo."] = "Когда останется только один враг, вы получите бонусные боеприпасы.", -- A_Space_Adventure:death02
      ["I forgot that she's the daughter of the chief, too..."] = "Я и забыл, что она ещё и дочь вождя...", -- A_Classic_Fairytale:backstab
      ["I found it! Hooray!"] = "Я нашёл её! Ура!", -- A_Space_Adventure:desert01
      ["If some good old explosives were enough to save Hogera …"] = "Если бы старой доброй взрывчатки хватило, чтобы спасти Хогеру…", -- A_Space_Adventure:final
      ["If they try coming here, they can have a taste of my delicious knuckles!"] = "Если сунутся сюда, получат на орехи от моих кулаков!", -- A_Classic_Fairytale:united
      ["If you agree to provide the information we need, you will be spared!"] = "Если согласишься выдать нужную нам информацию, тебе сохранят жизнь!", -- A_Classic_Fairytale:shadow
      ["If you can get that crate fast enough, your beloved \"princess\" may go free."] = "Если успеешь достать тот ящик достаточно быстро, твоя драгоценная «принцесса» будет свободна.", -- A_Classic_Fairytale:journey
      ["If you decide to help us, though, we will no longer need to find a new governor for the island."] = "Но если решишь помочь нам, нам больше не придётся искать нового наместника для острова.", -- A_Classic_Fairytale:shadow
      ["If you don't want to slip away, you have to keep moving!"] = "Если не хотите соскользнуть, продолжайте двигаться!", -- Basic_Training_-_Movement
      ["If you get stuck, use your Desert Eagle or restart the mission!"] = "Если застряли, используйте Desert Eagle или перезапустите миссию!", -- A_Classic_Fairytale:journey
      ["If you get stuck, use your Desert Eagle or restart the mission!|"] = "Если застряли, используйте Desert Eagle или перезапустите миссию!|", -- A_Classic_Fairytale:journey
      ["If you help us you can keep the device if you find it but we'll keep everything else."] = "Если поможешь нам, сможешь забрать устройство, если найдёшь, а всё остальное останется нам.", -- A_Space_Adventure:fruit02
      ["If you hurt an enemy, you'll get one third of the damage dealt."] = "Когда вы раните врага, то получите треть нанесённого урона в виде здоровья.", -- A_Space_Adventure:death02
      ["If you injure a hedgehog you'll get 35% of the damage dealt."] = "Когда вы раните ёжика, то получите 35% от нанесённого урона.", -- A_Space_Adventure:death02
      ["If you just don’t care …"] = "Если вам просто всё равно…", -- Continental_supplies
      ["If you kill a hedgehog with the respective weapon your health points will be set to 100."] = "Если убьёте ёжика соответствующим оружием, ваше здоровье станет равно 100.", -- A_Space_Adventure:death02
      ["If you kill an enemy, your health will be set to 100."] = "Если убьёте врага, ваше здоровье восстановится до 100.", -- A_Space_Adventure:death02
      ["If you know what I mean..."] = "Если ты понимаешь, о чём я...", -- A_Classic_Fairytale:shadow
      ["If you miss a shot while trying to|re-attach, your rope is gone, too!"] = "Если вы промахнётесь при попытке|перецепиться, верёвка пропадёт!", -- Basic_Training_-_Rope
      ["If you say so..."] = "Ну, раз ты так говоришь...", -- A_Classic_Fairytale:shadow
      ["If you skip a turn then the turn time left will be added to your next turn."] = "Если пропустите ход, оставшееся время прибавится к следующему ходу.", -- A_Space_Adventure:fruit03
      ["If you wish to replay, there are other possible endings, too!"] = "Если захотите переиграть — есть и другие возможные концовки!", -- A_Classic_Fairytale:epil
      ["Igmund"] = "Джокер", -- User_Mission_-_Nobody_Laugh
      ["I grew sick of the oppression! I broke free!"] = "Мне надоело угнетение! Я вырвалась на свободу!", -- A_Classic_Fairytale:queen
      ["I guess I can't go far without fuel!"] = "Я полагаю, что не улечу далеко без топлива!", -- A_Space_Adventure:cosmos
      ["I guess we lost him!"] = "Я полагаю, мы потеряли его!", -- A_Space_Adventure:cosmos
      ["I guess you'll have to kill them."] = "Я полагаю, ты должен убить их.", -- A_Classic_Fairytale:dragon
      ["I have come to make you an offering..."] = "Я пришёл, чтобы сделать тебе предложение...", -- A_Classic_Fairytale:shadow
      ["I have heard that the local tribes say that many years ago some PAotH scientists were dumping their waste here."] = "Я слышал, как местные племена говорили, что давным давно учёные из ПАЕ сбрасывали сюда свои отходы.", -- A_Space_Adventure:desert01
      ["I have more important things to do!"] = "У меня есть более важные дела!", -- A_Classic_Fairytale:queen
      ["I have no idea where that mole disappeared...Can you see it?"] = "Я не понимаю, куда делся этот крот...Ты его видишь?", -- A_Classic_Fairytale:shadow
      ["I have only 3 hogs available and they are all cadets."] = "У меня есть только 3 ёжика, и все они кадеты.", -- A_Space_Adventure:fruit01
      ["I have to follow that alien."] = "Я должен следовать за этим инопланетянином.", -- A_Classic_Fairytale:backstab
      ["I have to get back to the village!"] = "Я должен вернуться обратно в деревню!", -- A_Classic_Fairytale:shadow
      ["I have to reach the surface as quickly as I can."] = "Мне нужно выбраться на поверхность как можно быстрее.", -- A_Space_Adventure:desert02
      ["I hope you are prepared for a small challenge, young one."] = "Я надеюсь ты подготовился к небольшому испытанию, юнец.", -- A_Classic_Fairytale:first_blood
      ["I just don't want to sink to your level."] = "Я просто не хочу опускаться до твоего уровня.", -- A_Classic_Fairytale:backstab
      ["I just forgot all checkpoints of incomplete missions."] = "Я только что забыл все контрольные точки незавершённых миссий.", -- A_Space_Adventure:cosmos
      ["I just found out that they have captured your princess!"] = "Я только что узнал, что они захватили вашу принцессу!", -- A_Classic_Fairytale:family
      ["I just want the strange device you found!"] = "Мне нужно лишь то странное устройство, что ты нашёл!", -- A_Space_Adventure:ice01
      ["I just wonder where Ramon and Spiky disappeared..."] = "Интересно, куда пропали Рамон и Колючий...", -- A_Classic_Fairytale:journey
