      ["I know, my hero!"] = "Знаю, мой герой!", -- A_Classic_Fairytale:epil
      ["I know that your resources are low due to the battle but I'll send two of my best hogs to assist you."] = "Знаю, после боя у вас мало ресурсов, поэтому я пошлю вам на помощь двух лучших ёжиков.", -- A_Space_Adventure:fruit02
      ["I … like being with you, too."] = "Мне… тоже нравится быть с тобой.", -- A_Classic_Fairytale:epil
      ["I'll get him!"] = "Я его достану!", -- A_Space_Adventure:cosmos
      ["I'll hold them off while you return to the village!"] = "Я задержу их, пока ты возвращаешься в деревню!", -- A_Classic_Fairytale:shadow
      ["I'll let you know whatever I know about him if you manage to catch me 3 times."] = "Я расскажу всё, что знаю о нём, если сумеешь поймать меня 3 раза.", -- A_Space_Adventure:moon02
      ["I'll make good use of it."] = "Я найду этому достойное применение.", -- A_Space_Adventure:cosmos
      ["I'll protect you!"] = "Я буду защищать тебя!", -- A_Classic_Fairytale:epil
      ["I love Dense Cloud now!"] = "Теперь я люблю Густую Тучу!", -- A_Classic_Fairytale:epil
      ["I love you."] = "Я люблю тебя.", -- A_Classic_Fairytale:epil
      ["I'm afraid I can't let you proceed!"] = "Боюсь, я не могу пустить вас дальше!", -- A_Classic_Fairytale:queen
      ["I'm afraid we cannot afford that."] = "Я боюсь мы не можем себе этого позволить.", -- A_Classic_Fairytale:queen
      ["Imagine those targets are the wolves that killed your parents! Take your anger out on them!"] = "Представь, что эти мишени — волки, убившие твоих родителей! Вымести на них всю ярость!", -- A_Classic_Fairytale:first_blood
      ["I'm...alive? How? Why?"] = "Я... жив? Как? Зачем?", -- A_Classic_Fairytale:backstab
      ["I'm a ninja."] = "Я ниндзя.", -- A_Classic_Fairytale:dragon
      ["I marked the place of their arrival. You're welcome!"] = "Я отметил место их прибытия. Не за что!", -- A_Classic_Fairytale:backstab
      ["I may lost this battle, but I haven't lost the war yet!"] = "Может, я и проиграл эту битву, но ещё не проиграл войну!", -- A_Space_Adventure:moon01
