      ["IMPORTANT: To see the mission panel again, pause the game."] = "ВАЖНО: чтобы снова увидеть панель миссии, поставьте игру на паузу.", -- Basic_Training_-_Movement
      ["Impressive...you are still dry as the corpse of a hawk after a week in the desert..."] = "Впечатляет... ты всё ещё сух, как тушка ястреба после недели в пустыне...", -- A_Classic_Fairytale:first_blood
      ["%i ms"] = "%i мс", -- Gravity
      ["I'm so glad this is finally over!"] = "Я так рад, что это наконец-то закончилось!", -- A_Space_Adventure:final
      ["I'm so scared!"] = "Мне так страшно!", -- A_Classic_Fairytale:united
      ["I'm still low on hogs. If you are not afraid I could use a set of extra hands."] = "У меня всё ещё не хватает ёжиков. Если не боишься, мне бы пригодилась пара лишних рук.", -- A_Space_Adventure:fruit02
      ["I'm still with the aliens."] = "Я всё ещё на стороне пришельцев.", -- A_Classic_Fairytale:queen
      ["I'm terribly sorry!"] = "Мне ужасно жаль!", -- A_Classic_Fairytale:queen
      ["I'm the spy! I've been giving you out!"] = "Я шпион! Это я вас выдавала!", -- A_Classic_Fairytale:queen
      ["In am also entrusting you with some rope."] = "Я также доверяю тебе немного верёвок.", -- A_Space_Adventure:cosmos
      ["In case you haven't noticed, I'm a woman, too!"] = "Если вы не заметили, я тоже женщина!", -- A_Classic_Fairytale:queen
      ["Increase the dust storm damage by sacrificing|your invulnerable ammo."] = "Увеличьте урон пыльной бури, пожертвовав|неуязвимостью.", -- Continental_supplies
      ["Incredible..."] = "Невероятно...", -- A_Classic_Fairytale:shadow
      ["Indestructible Girder: [2]"] = "Неразрушимая балка: [2]", -- HedgeEditor
      ["Indestructible Land: [2]"] = "Неразрушимая земля: [2]", -- HedgeEditor
      ["Indestructible Land"] = "Неразрушимая земля", -- HedgeEditor
